#!/usr/bin/env python3
"""Original MIT SH-2 report/home/Q diagnostic and synthetic XA media.

Primary oracle: docs/cd-drive-reports.md. Guest issues every command, polls
HIRQ/status, transfers all five Q words and computes their sums. No SDK/media.
"""
import argparse
import hashlib
from pathlib import Path
import struct
from build_cd_drive import command
from build_cd_filesystem import raw_xa
from build_scu import assembler

HERE = Path(__file__).resolve().parent
BASE = 0x0600E000


def build():
    def cmd(words, name, slot):
        return command(words, name, BASE + slot * 16)

    def operand_command(words, name, slot, operand, index):
        s = cmd(words, name, slot)
        needle = f'load {words[index]:#x},r0\nmov.w r0,@r1\n'
        assert needle in s
        return s.replace(needle, f'load {operand:#x},r2\nmov.w @r2,r0\nmov.w r0,@r1\n', 1)

    def wait(name, slot, status):
        return (f'{name}_loop:\n' + cmd([0, 0, 0, 0], name, slot)
                + f'load {BASE + slot * 16:#x},r1\nmov.l @r1,r0\n'
                + f'load 0xf00,r2\nand r2,r0\nload {status << 8:#x},r2\n'
                + f'cmp/eq r2,r0\nbt {name}_done\nbra {name}_loop\nnop\n{name}_done:\n')

    def q(name, slot, record):
        s = cmd([0x2000, 0, 0, 0], name, slot)
        s += f'load 0x25818000,r4\nload {BASE + 0x800 + record * 32:#x},r5\nmov #0,r6\n'
        for _ in range(5):
            s += 'mov.w @r4,r0\nextu.w r0,r0\nadd r0,r6\nmov.l r0,@r5\nadd #4,r5\n'
        s += 'mov.l r6,@r5\n'
        return s + cmd([0x0600, 0, 0, 0], name + '_end', slot + 1)

    s = cmd([0x0400, 1, 0, 0], 'init', 0)
    s += cmd([0x3000, 0, 0, 0], 'connect', 29)
    s += operand_command([0x1180, 181, 0, 0], 'seek_operand', 1, 0x100, 1)
    s += wait('seek_done', 2, 1)
    s += q('initial_q', 3, 0)
    s += operand_command([0x1100, 0, 0, 0], 'home_operand', 5, 0x104, 0)
    s += cmd([0, 0, 0, 0], 'home_report', 6)
    s += q('home_q', 7, 1)
    s += cmd([0x11FF, 0xFFFF, 0, 0], 'pause_home', 9)
    s += wait('pause_home_done', 10, 1)
    s += q('paused_q', 11, 2)
    s += cmd([0x0500, 0, 0, 0], 'open', 13)
    s += q('open_q', 14, 3)
    s += cmd([0x0400, 1, 0, 0x8001], 'close', 16)
    s += cmd([0x1080, 173, 0x80, 1], 'play_bad', 17)
    s += wait('error', 18, 9)
    s += q('error_q', 19, 4)
    s += cmd([0x11FF, 0xFFFF, 0, 0], 'pause_error', 21)
    s += wait('error_recovery', 22, 1)
    s += q('recovered_q', 23, 5)
    s += cmd([0x1080, 174, 0x80, 1], 'play_good', 25)
    s += wait('good_done', 26, 1)
    s += cmd([0x6100, 0, 0, 1], 'get_sector', 27)
    s += 'load 0x25818000,r1\nmov.w @r1,r0\nextu.w r0,r0\nload 0x0600efe0,r1\nmov.l r0,@r1\n'
    s += cmd([0x0600, 0, 0, 0], 'end_sector', 28)
    s += 'load 0x0600effc,r1\nload 0x600d,r0\nmov.l r0,@r1\nsleep\n'
    rom = bytearray(524288)
    struct.pack_into('>II', rom, 0, 0x200, 0x06100000)
    struct.pack_into('>HHH', rom, 0x100, 181, 0, 0x1100)
    code = assembler.assemble(s, base=0x200)
    rom[0x200:0x200 + len(code)] = code
    lines = ['# Original MIT report/home/Q guest. Generated by build_cd_reports.py.',
             '# Operands: 0100 seek FAD; 0104 home opcode (0000 omits stop).']
    for at in range(0, len(rom), 16):
        if any(rom[at:at + 16]):
            lines.append(f'{at:04X} ' + ' '.join(f'{w:04X}' for w in struct.unpack('>8H', rom[at:at + 16])))
    files = {'cd-reports.hex': ('\n'.join(lines) + '\n').encode(),
             'cd-reports.cue': b'FILE "cd-reports.bin" BINARY\nTRACK 01 MODE2/2352\nINDEX 01 00:00:00\n'}
    for payload, name in [(0x69, 'cd-reports.bin'), (0xA6, 'cd-reports-changed.bin')]:
        raw = bytearray().join(raw_xa(bytes([payload]) * 2048, fad, 0) for fad in range(150, 250))
        raw[23 * 2352 + 24] ^= 0x5A
        files[name] = raw
    return files, hashlib.sha256(rom).hexdigest()


if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    files, digest = build()
    for name, data in files.items():
        if args.check:
            assert (HERE / name).read_bytes() == data, f'Rebuild {name}'
        else:
            (HERE / name).write_bytes(data)
        print(f'{"Verified" if args.check else "Built"} {name}; SHA-256 {hashlib.sha256(data).hexdigest()}')
    print(f'Expanded ROM SHA-256 {digest}')
